	if m.ListenAddress == nil {
		return protoerrors.NewErrMissingInvalidData(nil, "field ListenAddress is required")
	}

	// Validate MaxRequestSize (assert_gt: 0)
	if m.MaxRequestSize <= 0 {
		return protoerrors.NewErrMissingInvalidData(nil, "field MaxRequestSize must be > 0, got: %v", m.MaxRequestSize)
	}
	// Validate RequestTimeoutSeconds (assert_duration: POSITIVE)
	if m.RequestTimeoutSeconds <= 0 {
		return protoerrors.NewErrMissingInvalidData(nil, "field RequestTimeoutSeconds must be positive (> 0), got: %d", m.RequestTimeoutSeconds)
	}

	// Validate ShutdownTimeoutSeconds (assert_duration: POSITIVE)
	if m.ShutdownTimeoutSeconds <= 0 {
		return protoerrors.NewErrMissingInvalidData(nil, "field ShutdownTimeoutSeconds must be positive (> 0), got: %d", m.ShutdownTimeoutSeconds)
	}

	// Validate TrustedCas (assert_max_size: 32)
	if len(m.TrustedCas) > 32 {
		return protoerrors.NewErrMissingInvalidData(nil, "field TrustedCas exceeds max size of 32, got: %d", len(m.TrustedCas))
	}

	// Validate SpiffeTrustDomain (assert_max_length: 256)
	if len(m.SpiffeTrustDomain) > 256 {
		return protoerrors.NewErrMissingInvalidData(nil, "field SpiffeTrustDomain must be at most 256 characters, got: %d", len(m.SpiffeTrustDomain))
	}

	// Validate LocationPath (assert_max_length: 512)
	if len(m.LocationPath) > 512 {
		return protoerrors.NewErrMissingInvalidData(nil, "field LocationPath must be at most 512 characters, got: %d", len(m.LocationPath))
	}

