	if len(m.SpiffeTrustDomain) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field SpiffeTrustDomain exceeds max size of 32768 bytes, got: %d", len(m.SpiffeTrustDomain))
	}

	// Validate LocationPath (default max size: 32768 bytes)
	if len(m.LocationPath) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field LocationPath exceeds max size of 32768 bytes, got: %d", len(m.LocationPath))
	}

	// Validate Endpoints nested messages
	for i, val := range m.Endpoints {
		if err := host.ValidateHostWithDepth(val, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field Endpoints[%d] validation failed", i)
		}
	}

	// Validate PrivateKey nested message
	if m.PrivateKey != nil {
		if err := key.ValidateKeyWithDepth(m.PrivateKey, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field PrivateKey validation failed")
		}
	}

	// Validate ListenAddress nested message
	if m.ListenAddress != nil {
		if err := host.ValidateHostWithDepth(m.ListenAddress, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field ListenAddress validation failed")
		}
	}

	// Validate Logger nested message
	if m.Logger != nil {
		if err := logger.ValidateLoggerConfigWithDepth(m.Logger, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field Logger validation failed")
		}
	}

	// Validate TrustedCas nested messages
	for i, val := range m.TrustedCas {
		if err := x509.ValidateX509CertWithDepth(val, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field TrustedCas[%d] validation failed", i)
		}
	}

	return nil
